/* vt3rt: loader, indirect-call dispatch, and x87 helpers for recompiled code. */
#include "vt3rt.h"

#include "vt3/vt3_guest.h"
#include "vt3shim/shim.h"
#include "vt3shim/thunk.h"

#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <time.h>
#include <unistd.h>

/* The shim is the native runtime's (runtime/shim). Its adapter table is
 * generated by gen_adapters.py from the same headers. */

uint8_t *vt_mem = NULL;

#define VT_STACK_TOP 0x10000000u
#define VT_TEB 0x0FE00000u          /* inside the arena, below the stack */
#define VT_TOKEN_BASE 0xFFFF0000u   /* import tokens, never memory */
#define VT_SHIM_TOKEN_BASE 0xFFF00000u /* shim functions, for guest vtables (vt3shim_fn_token) */
#define VT_SENTINEL_RET 0xFFFFFFF0u /* return address for the entry call */

typedef struct {
    uint32_t addr;
    vt3_fnptr fn;
    const char *name;
} icent;

static icent *itab = NULL;
static size_t nitab = 0;
static int trace = 0;

uint64_t vt_rdtsc(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

void vt_die_at(uint32_t addr, uint32_t detail)
{
    fflush(stdout);
    fprintf(stderr, "vt3: fault at guest %08x (detail %08x)\n", addr, detail);
    exit(99);
}

void vt_unsupported_at(uint32_t addr, const char *text)
{
    fflush(stdout);
    fprintf(stderr, "vt3: unsupported instruction at %08x: %s\n", addr, text);
    exit(98);
}

static int icent_cmp(const void *a, const void *b)
{
    const icent *x = a, *y = b;
    return (x->addr > y->addr) - (x->addr < y->addr);
}

void vt_icall(vt3_cpu *c, uint32_t target)
{
    size_t lo = 0, hi = nitab;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (itab[mid].addr < target) lo = mid + 1;
        else hi = mid;
    }
    if (lo >= nitab || itab[lo].addr != target) {
        fflush(stdout);
        fprintf(stderr, "vt3: indirect transfer to unknown guest address %08x\n", target);
        exit(97);
    }
    icent *e = &itab[lo];
    if (!e->fn) {
        fflush(stdout);
        fprintf(stderr, "vt3: unimplemented import %s\n", e->name);
        exit(96);
    }
    if (trace) {
        /* Show the first argument as a string for the calls that take names. */
        const char *arg = "";
        if (!strcmp(e->name, "LoadLibraryA") || !strcmp(e->name, "GetModuleHandleA") ||
            !strcmp(e->name, "GetProcAddress") || !strcmp(e->name, "CreateFileA")) {
            uint32_t p = rd32(c->esp + 4);
            if (p && p < (1u << 30)) arg = (const char *)(vt_mem + p);
        }
        fprintf(stderr, "vt3: call %s %s from %08x", e->name, arg, rd32(c->esp));
        /* Walk the EBP chain: the CRT and most game code keep frame pointers. */
        uint32_t bp = c->ebp;
        for (int depth = 0; depth < 6 && bp && bp < (1u << 30); depth++) {
            fprintf(stderr, " <- %08x", rd32(bp + 4));
            bp = rd32(bp);
        }
        fprintf(stderr, "\n");
    }
    e->fn(c);
}

/* ---- x87 ----------------------------------------------------------------- */

double vt_ldf32(uint32_t a)
{
    float f;
    memcpy(&f, vt_mem + a, 4);
    return f;
}

double vt_ldf64(uint32_t a)
{
    double d;
    memcpy(&d, vt_mem + a, 8);
    return d;
}


void vt_stf32(uint32_t a, double v)
{
    float f = (float)v;
    memcpy(vt_mem + a, &f, 4);
}

void vt_stf64(uint32_t a, double v)
{
    memcpy(vt_mem + a, &v, 8);
}




uint32_t vt_cvt_i32(double v, int tr)
{
    double r = tr ? trunc(v) : nearbyint(v);
    if (!(r >= -2147483648.0 && r < 2147483648.0)) return 0x80000000u;
    return (uint32_t)(int32_t)r;
}

uint32_t vt_fcmp_d(double a, double b)
{
    if (isnan(a) || isnan(b)) return 0x7u;
    if (a < b) return 0x1u;
    if (a == b) return 0x2u;
    return 0x0u;
}

vt_xmm vt_ldx(uint32_t a)
{
    vt_xmm v;
    memcpy(v.b, vt_mem + a, 16);
    return v;
}

void vt_stx(uint32_t a, vt_xmm v)
{
    memcpy(vt_mem + a, v.b, 16);
}

/* ---- loader -------------------------------------------------------------- */

/* Import name ("DLL!Name" or "Name") to shim adapter. NULL when the shim has none. */
static vt3_fnptr shim_lookup(const char *name)
{
    const char *bare = name;
    for (const char *p = name; *p; p++)
        if (*p == '!') bare = p + 1;
    for (size_t i = 0; i < vt3_shim_count; i++)
        if (strcmp(vt3_shim_table[i].name, bare) == 0) return vt3_shim_table[i].fn;
    return NULL;
}

/* Guest address for shim function `name` (runtime/shim/include/vt3shim/thunk.h). */
uint32_t vt3shim_fn_token(const char *name)
{
    for (size_t i = 0; i < vt3_shim_count; i++)
        if (strcmp(vt3_shim_table[i].name, name) == 0) return VT_SHIM_TOKEN_BASE + 16u * (uint32_t)i;
    return 0;
}

/* Ordinal-only imports have no name in the import table. The shim binds by name, so map the
 * ordinals it needs. DSOUND ordinal 11 is DirectSoundCreate. */
static const char *shim_import_name(const vt3_import *im)
{
    if (strncmp(im->name, "ORD", 3) == 0 && im->dll && strcasecmp(im->dll, "DSOUND.dll") == 0 &&
        strtol(im->name + 3, NULL, 10) == 11)
        return "DirectSoundCreate";
    return im->name;
}

static void put32(uint32_t a, uint32_t v)
{
    memcpy(vt_mem + a, &v, 4);
}

/* Runs a guest function on the given stack, stdcall style, for the shim's threads and timers.
 * The arguments are pushed right to left, and a sentinel return address goes under them. The
 * callee pops its own arguments. */
static uint32_t guest_call_hook(uint32_t stack_top, uint32_t teb, uint32_t fn,
                                const uint32_t *args, uint32_t nargs)
{
    vt3_cpu c;
    memset(&c, 0, sizeof c);
    c.esp = stack_top;
    for (uint32_t i = nargs; i-- > 0;) {
        c.esp -= 4;
        put32(c.esp, args[i]);
    }
    c.esp -= 4;
    put32(c.esp, VT_SENTINEL_RET);
    c.fs_base = teb;
    c.fcw = 0x37Fu;
    vt_icall(&c, fn);
    return c.eax;
}

int vt3_run(const vt3_module *m, const char *image_path)
{
    trace = getenv("VT3_TRACE") != NULL;

    /* One guest arena from the native runtime. Guest address A is vt_mem + A,
     * so vt_mem is the host address of guest 0. vt3_g2h(0) is NULL by design,
     * so the base comes from the image address and is subtracted back out. */
    if (vt3_guest_init(VT3_GUEST_DEFAULT_BYTES) != 0) return 1;
    uint8_t *img_host = vt3_g2h(VT3_GUEST_IMAGE_BASE);
    if (!img_host) {
        fprintf(stderr, "vt3: guest arena too small for the image\n");
        return 1;
    }
    vt_mem = img_host - VT3_GUEST_IMAGE_BASE;

    FILE *f = fopen(image_path, "rb");
    if (!f) {
        fprintf(stderr, "vt3: cannot open %s\n", image_path);
        return 1;
    }
    size_t got = fread(vt_mem + m->image_base, 1, m->image_size, f);
    fclose(f);
    if (got != m->image_size) {
        fprintf(stderr, "vt3: %s is %zu bytes, expected %u\n", image_path, got, m->image_size);
        return 1;
    }

    /* TEB: the few fields the CRT and SEH read through FS. */
    put32(VT_TEB + 0x00, 0xFFFFFFFFu);          /* SEH chain end */
    put32(VT_TEB + 0x04, VT_STACK_TOP);         /* stack base */
    put32(VT_TEB + 0x08, VT_STACK_TOP - (1u << 20)); /* stack limit */
    put32(VT_TEB + 0x18, VT_TEB);               /* self */
    put32(VT_TEB + 0x30, VT_TEB + 0x1000);      /* PEB */

    vt3shim_set_game_root(getenv("VT3_GAME_ROOT") ? getenv("VT3_GAME_ROOT") : ".");
    if (vt3shim_init() != 0) return 1;
    vt3shim_set_guest_call(guest_call_hook);
    vt3shim_thread_begin_main();

    /* Imports: each IAT slot gets a unique token. Calls through the slot land in
     * the icall table, which maps the token to a shim. */
    size_t nimp = m->nimps;
    icent *tab = calloc(m->nfns + nimp + vt3_shim_count, sizeof *tab);
    if (!tab) return 1;
    size_t n = 0;
    for (size_t i = 0; i < m->nfns; i++) {
        tab[n].addr = m->fns[i].addr;
        tab[n].fn = m->fns[i].fn;
        tab[n].name = m->fns[i].name;
        n++;
    }
    for (size_t i = 0; i < nimp; i++) {
        const vt3_import *im = &m->imps[i];
        uint32_t tok = VT_TOKEN_BASE + 16u * (uint32_t)i;
        put32(im->slot, tok);
        tab[n].addr = tok;
        tab[n].fn = shim_lookup(shim_import_name(im));
        tab[n].name = im->name;
        n++;
    }
    for (size_t i = 0; i < vt3_shim_count; i++) {
        tab[n].addr = VT_SHIM_TOKEN_BASE + 16u * (uint32_t)i;
        tab[n].fn = vt3_shim_table[i].fn;
        tab[n].name = vt3_shim_table[i].name;
        n++;
    }
    qsort(tab, n, sizeof *tab, icent_cmp);
    itab = tab;
    nitab = n;

    vt3_cpu c = {0};
    c.esp = VT_STACK_TOP - 64;
    c.esp -= 4;
    put32(c.esp, VT_SENTINEL_RET);
    c.fs_base = VT_TEB;
    c.fcw = 0x37Fu;

    vt_icall(&c, m->entry);
    /* The entry is expected to call ExitProcess. Returning means it did not. */
    fflush(stdout);
    vt3shim_shutdown();
    vt3_guest_shutdown();
    return 0;
}
